import numpy as np
import pandas as pd
from itertools import product

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(dtype=float)
y = train['target'].to_numpy(dtype=int)

# standardize helper

def zfit(X):
    mean = X.mean(axis=0)
    std = X.std(axis=0)
    std[std == 0] = 1.0
    return mean, std

def zapply(X, mean, std):
    return (X - mean) / std

def stratified_folds(y, n_splits=5, seed=0):
    rng = np.random.default_rng(seed)
    folds = [[] for _ in range(n_splits)]
    for cls in np.unique(y):
        idx = np.flatnonzero(y == cls)
        rng.shuffle(idx)
        for i, j in enumerate(idx):
            folds[i % n_splits].append(j)
    return [np.array(sorted(f)) for f in folds]

folds = stratified_folds(y)


def acc(a,b):
    return (a==b).mean()


def predict_centroid(Xtr, ytr, Xva):
    means = {c: Xtr[ytr==c].mean(axis=0) for c in np.unique(ytr)}
    out=[]
    for x in Xva:
        d={c: np.sum((x-m)**2) for c,m in means.items()}
        out.append(min(d,key=d.get))
    return np.array(out)


def predict_nb(Xtr,ytr,Xva,var_smoothing=1e-9):
    classes = np.unique(ytr)
    priors = {c:(ytr==c).mean() for c in classes}
    means = {c:Xtr[ytr==c].mean(axis=0) for c in classes}
    vars_ = {c:Xtr[ytr==c].var(axis=0)+var_smoothing for c in classes}
    out=[]
    for x in Xva:
        scores={}
        for c in classes:
            v=vars_[c]
            m=means[c]
            scores[c] = np.log(priors[c]) -0.5*np.sum(np.log(2*np.pi*v)+((x-m)**2)/v)
        out.append(max(scores,key=scores.get))
    return np.array(out)


def predict_lda(Xtr,ytr,Xva,shrink=0.0):
    classes=np.unique(ytr)
    priors={c:(ytr==c).mean() for c in classes}
    means={c:Xtr[ytr==c].mean(axis=0) for c in classes}
    cov=np.cov(Xtr,rowvar=False,bias=True)
    d=cov.shape[0]
    cov=(1-shrink)*cov + shrink*np.eye(d)*np.trace(cov)/d
    cov += np.eye(d)*1e-6
    inv=np.linalg.pinv(cov)
    out=[]
    for x in Xva:
        scores={}
        for c in classes:
            m=means[c]
            scores[c] = x@inv@m - 0.5*m@inv@m + np.log(priors[c])
        out.append(max(scores,key=scores.get))
    return np.array(out)


def predict_knn(Xtr,ytr,Xva,k=5):
    out=[]
    for x in Xva:
        d=np.sum((Xtr-x)**2,axis=1)
        idx=np.argsort(d)[:k]
        vals,counts=np.unique(ytr[idx],return_counts=True)
        out.append(vals[np.argmax(counts)])
    return np.array(out)


def predict_logreg(Xtr,ytr,Xva,lr=0.1,l2=1.0,steps=3000):
    n,d=Xtr.shape
    w=np.zeros(d)
    b=0.0
    for t in range(steps):
        z=Xtr@w+b
        p=1/(1+np.exp(-np.clip(z,-30,30)))
        grad_w=(Xtr.T@(p-ytr))/n + l2*w/n
        grad_b=np.mean(p-ytr)
        eta=lr/(1+t*0.001)
        w-=eta*grad_w
        b-=eta*grad_b
    p=1/(1+np.exp(-np.clip(Xva@w+b,-30,30)))
    return (p>=0.5).astype(int)

models=[]
models.append(('centroid', lambda a,b,c: predict_centroid(a,b,c)))
for s in [1e-6,1e-4,1e-2,1e-1,1.0]:
    models.append((f'nb_{s}', lambda a,b,c,s=s: predict_nb(a,b,c,s)))
for sh in [0.0,0.1,0.3,0.5,0.8,0.95]:
    models.append((f'lda_{sh}', lambda a,b,c,sh=sh: predict_lda(a,b,c,sh)))
for k in [1,3,5,7,9,11]:
    models.append((f'knn_{k}', lambda a,b,c,k=k: predict_knn(a,b,c,k)))
for l2 in [0.01,0.1,1.0,10.0]:
    models.append((f'logreg_{l2}', lambda a,b,c,l2=l2: predict_logreg(a,b,c,l2=l2)))

for name,model in models:
    scores=[]
    for fold in folds:
        tr=np.setdiff1d(np.arange(len(y)), fold)
        va=fold
        Xtr,ytr=X[tr],y[tr]
        Xva,yva=X[va],y[va]
        mean,std=zfit(Xtr)
        Xtr=zapply(Xtr,mean,std)
        Xva=zapply(Xva,mean,std)
        pred=model(Xtr,ytr,Xva)
        scores.append(acc(yva,pred))
    print(name, round(float(np.mean(scores)),4), scores)
